def is_prime(num):
    """Checks if a number is prime."""
    if num <= 1:
        return False
    # Check divisibility from 2 up to the square root of num
    i = 2
    while i * i <= num:
        if num % i == 0:
            return False
        i += 1
    return True
def count_up_to(n):
    """Implements a function that takes a non-negative integer and returns an array 
    of prime numbers that are strictly less than n.
    """
    primes = []

    # Iterate from 2 up to (but not including) n
    for num in range(2, n):
        if is_prime(num):
            primes.append(num)

    return primes
